1294:             // full-batch: real payload read bytes for the completion master
1295:             // (slave port 2).  DS walk (3) and CPU (0) are excluded.
1296:             if (full_era && (((s_ddr_ar_i >> 4) & 3u) == 2u)) {
1297:                 const unsigned ch = (unsigned)((s_ddr_ar_i >> 2) & 1u);
1298:                 ++full_ar_n[ch];
