1507:     // Read NEXT_ID (0x28) to issue the programmed transfer and return the
1508:     // reserved functional ID so DONE can be matched exactly.
1509:     uint64_t trigger(bool sel) {
1510:         return cfg_rd(sel, REG_NEXT);
1511:     }
1512: 
1513:     // Poll DONE (0x30) until it equals the ID reserved by trigger().
1514:     void wait_done(bool sel, uint64_t expected, const char* where) {
1515:         long t = 0;
1516:         for (; t < WATCHDOG_CYCLES; ++t) {
1517:             tick();
1518:             if (g_cycle - last_progress_cycle > WATCHDOG_CYCLES) {
1519:                 dump_stall(where);
1520:                 throw TestFailure("watchdog: no handshake progress while waiting DONE");
1521:             }
1522:             if (g_cycle - scenario_start > scenario_budget) {
1523:                 dump_stall(where);
1524:                 throw TestFailure("scenario budget exhausted while waiting DONE");
1525:             }
1526:             uint64_t d = cfg_rd(sel, REG_DONE);
1527:             if (d == expected) return;
1528:         }
1529:         dump_stall(where);
1530:         throw TestFailure("DONE never reached the expected ID");
1531:     }
